def add_final_batch():
    os.makedirs('data/phase2-recipes', exist_ok=True)
    for country, data in FINAL_BATCH.items():
        with open(f"data/phase2-recipes/{country.lower()}-phase2-authentic.json", 'w') as f:
            json.dump(data, f, indent=2, ensure_ascii=False)
        recipes = sum(len(data.get(cat, [])) for cat in ['breakfast', 'lunch', 'dinner', 'snacks', 'desserts', 'nonAlcoholicDrinks', 'alcoholicDrinks'])
        print(f"✓ {country:<15} | {recipes} recipes")

if __name__ == "__main__":
    print("\n🌍 PHASE 2 FINAL BATCH: USA, Germany, Greece")
    print("="*80 + "\n")
    add_final_batch()
